1. We will start with the smallest five-digit number, which is 10000.
2. We will loop through each number, checking if it has all different digits and if it is divisible by each of its non-zero digits.
3. Once we find the first number that meets these criteria, we will confirm it is the smallest such number.

Now, let's implement this in Python.
```python
def has_all_different_digits(n):
    digits = str(n)
    return len(set(digits)) == len(digits)

def is_divisible_by_each_non_zero_digit(n):
    digits = [int(d) for d in str(n)]
    for d in digits:
        if d == 0:
            continue
        if n % d != 0:
            return False
    return True

def find_smallest_five_digit_number():
    for num in range(10000, 100000):
        if has_all_different_digits(num) and is_divisible_by_each_non_zero_digit(num):
            return num

smallest_five_digit_number = find_smallest_five_digit_number()
print(smallest_five_digit_number)
